  }, [options, selectedIds])

  const triggerLabel =
    selectedLabels.length === 0
      ? emptyLabel
      : selectedLabels.length === 1
        ? selectedLabels[0]
        : `${selectedLabels.length} ${selectionNoun}`

  return (
