 * Utilidades para bÃºsqueda de Aranceles
 * 
 * Funciones para encontrar aranceles basados en contexto de ROL/Demanda
 * para auto-completar montos en Boletas/Estampos
 */

import { prisma } from '@/lib/prisma'

/**
 * Busca el arancel correcto para un Estampo dado un contexto de ROL
 * 
 * Orden de prioridad:
 * 1. Arancel especÃ­fico del Abogado para este Estampo en este Banco
 * 2. Arancel del Banco (banco-wide) para este Estampo
 * 3. null (no encontrado, monto debe ser manual)
 * 
 * @param officeId - ID de la oficina
 * @param bancoId - ID del banco (puede venir de demanda o abogado.bancoId)
 * @param abogadoId - ID del abogado (de demanda.abogadoId)
 * @param estampoId - ID del estampo seleccionado
 * @returns Arancel encontrado con monto y fuente, o null si no se encontrÃ³
 * 
 * @example
 * const arancel = await lookupArancel(1, 5, 10, "abc123")
 * if (arancel) {
 *   console.log(`Arancel: $${arancel.monto} (${arancel.source})`)
 *   // Arancel: $14000 (abogado)
 * }
 */
export async function lookupArancel(
  officeId: number,
  bancoId: number | null,
  abogadoId: number | null,
  estampoId: string
): Promise<{ monto: number; source: 'abogado' | 'banco' } | null> {
  if (!bancoId || !estampoId) {
    return null
  }

  // Prioridad 1: Arancel especÃ­fico del Abogado
  if (abogadoId) {
    const abogadoArancel = await prisma.arancel.findFirst({
      where: {
        officeId,
        bancoId,
        abogadoId,
        estampoId,
        activo: true,
      },
    })

    if (abogadoArancel) {
      return { monto: abogadoArancel.monto, source: 'abogado' }
    }
  }

  // Prioridad 2: Arancel banco-wide
  const bancoArancel = await prisma.arancel.findFirst({
    where: {
      officeId,
      bancoId,
      abogadoId: null,
      estampoId,
      activo: true,
    },
  })

  if (bancoArancel) {
    return { monto: bancoArancel.monto, source: 'banco' }
  }

  // No se encontrÃ³ arancel
  return null
}

/**
 * Busca el arancel correcto para un EstampoBase categorÃ­a dado un contexto de ROL
 * 
 * Orden de prioridad (igual que legacy):
 * 1. Arancel especÃ­fico del Abogado para esta categorÃ­a en este Banco
 * 2. Arancel del Banco (banco-wide) para esta categorÃ­a
 * 3. null (no encontrado, monto debe ser manual)
 * 
 * @param officeId - ID de la oficina
 * @param bancoId - ID del banco (puede venir de demanda o abogado.bancoId)
 * @param abogadoId - ID del abogado (de demanda.abogadoId)
 * @param categoria - CategorÃ­a del EstampoBase (ej: 'BUSQUEDA_NEGATIVA')
 * @returns Arancel encontrado con monto y fuente, o null si no se encontrÃ³
 */
export async function lookupArancelByCategoria(
  officeId: number,
  bancoId: number | null,
  abogadoId: number | null,
  categoria: string
): Promise<{ monto: number; source: 'abogado' | 'banco' } | null> {
  if (!bancoId || !categoria) {
    return null
  }

  // Prioridad 1: Arancel especÃ­fico del Abogado
  if (abogadoId) {
    const abogadoArancel = await prisma.arancel.findFirst({
      where: {
        officeId,
        bancoId,
        abogadoId,
        estampoBaseCategoria: categoria,
        activo: true,
      },
    })

    if (abogadoArancel) {
      return { monto: abogadoArancel.monto, source: 'abogado' }
    }
  }

  // Prioridad 2: Arancel banco-wide
  const bancoArancel = await prisma.arancel.findFirst({
    where: {
      officeId,
      bancoId,
      abogadoId: null,
      estampoBaseCategoria: categoria,
      activo: true,
    },
  })

  if (bancoArancel) {
    return { monto: bancoArancel.monto, source: 'banco' }
  }

  return null
}

/**
