    const normalizedEjecutados: IncomingEjecutado[] | undefined = Array.isArray(ejecutados)
      ? ejecutados.map((ej: any) => ({
          id: typeof ej.id === 'string' && ej.id.trim() ? ej.id.trim() : null,
          nombre: ej.nombre,
